var a=`1141-apple-pie`;var t=`world-1141`;var n=`US`;var r=`northern-america`;var o=8;var s=149;var l={en:`Apple Pie`,ua:`Американський яблучний пиріг`};var d={en:`Apple Pie is a dish from United States prepared with all-purpose flour, apple, lemon juice. This is a home-scale version with measured ingredients in the individual steps where they are used.`,ua:`Американський яблучний пиріг, страва кухні країни Сполучені Штати Америки, яку готують із таких продуктів: пшеничне борошно універсальне, яблуко, лимонний сік. Кількості в домашньому рецепті прив’язані до окремих етапів приготування.`};var u=[{en:`Mix the dough ingredients, knead until smooth and elastic, then cover and rest for about 25 minutes.`,ua:`Змішайте складники тіста, вимісіть до гладкості й еластичності, накрийте та залиште приблизно на 25 хвилин.`,t:[`mixing`,`kneading`,`resting-dough`],m:25,i:[[`all-purpose-flour`,440,`g`],[`unsalted-butter`,230,`g`],[`water`,110,`ml`],[`table-salt`,5,`g`]]},{en:`Wash and prepare the listed produce; dice or chop evenly for a consistent texture.`,ua:`Вимийте й підготуйте зазначені продукти; наріжте рівномірними кубиками або дрібними шматочками.`,t:[`chopping`,`dicing`],m:12,i:[[`apple`,900,`g`],[`white-granulated-sugar`,130,`g`],[`ground-cinnamon`,7,`g`],[`lemon-juice`,28,`ml`]]},{en:`Layer the already prepared filling and base evenly in the baking dish or pan.`,ua:`Рівномірно викладіть уже підготовлені основу й начинку шарами у форму чи на деко.`,t:[`layered-assembly`],m:10,i:[]},{en:`Bake the shaped or assembled mixture in a preheated oven for about 52 minutes until set and cooked through.`,ua:`Випікайте сформовану або складену масу в розігрітій духовці приблизно 52 хвилин до готовності.`,t:[`baking`],m:52,i:[]},{en:`Refrigerate the prepared mixture for about 50 minutes, cooling perishable foods promptly and never holding cooked rice warm at room temperature.`,ua:`Охолоджуйте підготовлену масу в холодильнику близько 50 хвилин; швидко охолоджуйте швидкопсувні продукти й не тримайте готовий рис у теплі при кімнатній температурі.`,t:[`rapid-chilling`],m:50,i:[]}];var p={slug:a,id:t,country:`US`,region:r,servings:8,minutes:149,title:l,text:d,steps:u};export{n as country,p as default,t as id,s as minutes,r as region,o as servings,a as slug,u as steps,d as text,l as title};